const cities={RUH:{name:'Riyadh',country:'Saudi Arabia',emoji:'🇸🇦'},DXB:{name:'Dubai',country:'UAE',emoji:'🇦🇪'},LHR:{name:'London',country:'United Kingdom',emoji:'🇬🇧'},JFK:{name:'New York',country:'United States',emoji:'🇺🇸'},HND:{name:'Tokyo',country:'Japan',emoji:'🇯🇵'},CDG:{name:'Paris',country:'France',emoji:'🇫🇷'},IST:{name:'Istanbul',country:'Türkiye',emoji:'🇹🇷'},CPT:{name:'Cape Town',country:'South Africa',emoji:'🇿🇦'},SYD:{name:'Sydney',country:'Australia',emoji:'🇦🇺'},DEL:{name:'Delhi',country:'India',emoji:'🇮🇳'}};
const rates={SAR:1,USD:3.75,EUR:4.05,GBP:4.75,AED:1.02,INR:.045};
const fares={Standard:0,'First class':30,'Business class':100};
const plans={Week:12,Month:39,Year:100};
const stages=['Home','Taxi','Check-in','Security','Gate','In flight','Landing'];
const defaults={stage:0,coins:500,origin:'RUH',destination:'DXB',flightClass:'Standard',pass:'No pass',admin:false,adminName:'Aviator',bagDone:false,flightRound:0,stars:0,house:0};
let state={...defaults,...JSON.parse(localStorage.getItem('cloudbound-save')||'{}')};
let currency='SAR',chosenClass='First class',chosenPlan='Week',flightTarget=1;
const game=document.getElementById('game');
function save(){localStorage.setItem('cloudbound-save',JSON.stringify(state));}
function city(code){return cities[code]||cities.RUH}
function toast(msg){const old=document.querySelector('.toast');if(old)old.remove();const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.appendChild(el);setTimeout(()=>el.remove(),2300)}
function setStage(n){state.stage=n;save();render()}
function art(){const s=state.stage;let scene=s===0?'Home sweet home':s===1?'Your ride is here':s===2?'Check-in desk':s===3?'Security check':s===4?'Ready for take-off':s===5?'Above the clouds':'Touchdown!';let graphic=s<=1?'<div class="house"><i class="window"></i></div><div class="taxi-art">🚕</div>':s<=3?'<div class="airport-art">🛄</div>':s===4?'<div class="airport-art">🛫</div><div class="boarding-plane">✈️</div>':s===5?'<div class="boarding-plane">✈️</div><div class="cloud c2"></div>':'<div class="airport-art">🛬</div>';return `<div class="scene-art"><div class="sun"></div><div class="cloud"></div><div class="cloud c2"></div><div class="hills back"></div><div class="hills"></div>${graphic}<span class="art-label">${scene}</span></div>`}
function routeCard(){return `<div class="route-card"><div class="route-line"><div><div class="airport-code">${state.origin}</div><div class="route-city">${city(state.origin).name}</div></div><div><div class="route-connector"></div></div><div style="text-align:right"><div class="airport-code">${state.destination}</div><div class="route-city">${city(state.destination).name}</div></div></div><div class="flight-meta"><span>✈ CB ${String(218+state.stage*7).padStart(3,'0')}</span><span>${state.flightClass}</span><span>✦ ${state.stars} stars</span></div></div><div class="ticket-mini"><div><small>Landing on your ticket</small><b>${city(state.destination).emoji} ${city(state.destination).name}</b></div><span class="ticket-class">${state.pass}</span></div>`}
function progress(){return `<div class="progress">${stages.map((s,i)=>`<div class="progress-step ${i===state.stage?'active':i<state.stage?'done':''}"><span class="number">${i<state.stage?'✓':i+1}</span><span>${s}</span></div>${i<stages.length-1?'<span class="progress-line"></span>':''}`).join('')}</div>`}
function panel(){let title='',copy='',button='',tag='YOUR JOURNEY';switch(state.stage){case 0:title='A little adventure awaits.';copy='Pick a destination, spend a few game coins on your home, then call a taxi. Your landing city is printed on your ticket from the very start.';button=`<button class="primary" onclick="openRoute()">Plan my trip <span>→</span></button>`;tag='START AT HOME';break;case 1:title='Taxi to the terminal';copy='Your bags are ready. The airport taxi costs 35 game coins — no real-world money needed to get going.';button=`<button class="primary" onclick="rideTaxi()">Order airport taxi · 35 coins</button>`;tag='PICK-UP';break;case 2:title='Pack light, fly happy.';copy='Check your bag at the counter. Keep it under 20 kg and your carry-on close by.';button=`<button class="primary" onclick="openBag()">Check my luggage →</button>`;tag='BAG DROP';break;case 3:title='A quick security check';copy='Select the item that needs to go in the security tray. You can keep your snacks and small luggage with you.';button=`<button class="primary" onclick="securityDone()">I’m ready for security →</button>`;tag='SECURITY';break;case 4:title='Your gate is calling.';copy='Ticket in hand? Head to the boarding place and scan your pass. Destination is ${city(state.destination).name}.';button=`<button class="primary" onclick="openTicket()">View ticket & board →</button>`;tag='BOARDING';break;case 5:title='Pilot the friendly skies.';copy='Choose a flight lane each turn. Dodge the clouds, collect sky stars, and guide your plane to ${city(state.destination).name}.';button=`<div class="flight-controls"><div class="event-banner" id="flight-event">Pick a lane for this stretch of sky.</div><div class="lane-buttons"><button class="lane-btn" onclick="fly('left')">← Left</button><button class="lane-btn" onclick="fly('center')">↑ Center</button><button class="lane-btn" onclick="fly('right')">Right →</button></div><span class="hint">Flight ${state.flightRound}/5 · Stars collected: ${state.stars}</span></div>`;tag='IN FLIGHT';break;case 6:title='Welcome to ${city(state.destination).name}!'.replace('${city(state.destination).name}',city(state.destination).name);copy='You made it! Your trip is complete. Enjoy the city, collect your arrival bonus, or plan another journey.';button=`<button class="primary" onclick="newTrip()">Plan another trip →</button>`;tag='LANDED';break;}let heading=state.stage===6?`Welcome to ${city(state.destination).name}!`:title;let options=state.stage===0?`<div class="select-row"><div class="field"><label>DEPARTING FROM</label><select id="origin-select">${Object.keys(cities).map(c=>`<option value="${c}" ${c===state.origin?'selected':''}>${cities[c].emoji} ${cities[c].name} (${c})</option>`).join('')}</select></div><div class="field"><label>FLYING TO</label><select id="dest-select">${Object.keys(cities).filter(c=>c!==state.origin).map(c=>`<option value="${c}" ${c===state.destination?'selected':''}>${cities[c].emoji} ${cities[c].name} (${c})</option>`).join('')}</select></div></div><div class="actions">${button}<button class="secondary" onclick="openShop()">✦ Cabin & fun passes</button></div>`:state.stage===3?`<div class="actions">${button}</div>`:`<div class="actions">${button}</div>`;let sub=state.stage===0?`<div class="feature-list"><div class="feature"><b>🎒 Pack & go</b>Easy luggage mini-game</div><div class="feature"><b>🛩 Pilot it</b>Five turns in the sky</div><div class="feature"><b>🌍 Explore</b>10 world destinations</div></div>`:'';return `<section class="scene-card">${art()}<div class="card-body"><div class="card-heading"><div><span class="eyebrow">${tag}</span><h2>${heading}</h2><p>${copy}</p></div><span class="tag">${state.stage===0?'✦ Ready':`${state.stage+1} / 7`}</span></div>${options}${sub}</div></section>`}

