iv>`;tag='IN FLIGHT';break;case 6:title=`Welcome to ${city(state.destination).name}!`;copy='You made it! Your trip is complete. Enjoy the city, collect your arrival bonus, or plan another journey.';button=`<button class="primary" onclick="newTrip()">Plan another trip →</button>`;tag='LANDED';break;}let options=state.stage===0?`<div class="select-row"><div class="field"><label>DEPARTING FROM</label><select id="origin-select">${Object.keys(cities).map(c=>`<option value="${c}" ${c===state.origin?'selected':''}>${cities[c].emoji} ${cities[c].name} (${c})</option>`).join('')}</select></div><div class="field"><label>FLYING TO</label><select id="dest-select">${Object.keys(cities).filter(c=>c!==state.origin).map(c=>`<option value="${c}" ${c===state.destination?'selected':''}>${cities[c].emoji} ${cities[c].name} (${c})</option>`).join('')}</select></div></div><div class="actions">${button}<button class="secondary" onclick="openShop()">✦ Cabin & fun passes</button></div>`:`<div class="actions">${button}</div>`;let sub=state.stage===0?`<div class="feature-list"><div class="feature"><b>🎒 Pack & go</b>Easy luggage mini-game</div><div class="feature"><b>🛩 Pilot it</b>Five turns in the sky</div><div class="feature"><b>🌍 Explore</b>10 world destinations</div></div>`:'';return `<section class="scene-card">${art()}<div class="card-body"><div class="card-heading"><div><span class="eyebrow">${tag}</span><h2>${title}</h2><p>${copy}</p></div><span class="tag">${state.stage===0?'✦ Ready':`${state.stage+1} / 7`}</span></div>${options}${sub}</div></section>`}
function side(){return `<aside class="side-card"><h3 class="side-title">Your trip <span class="eyebrow">✦ LIVE TICKET</span></h3>${routeCard()}<div class="side-bottom"><p class="hint">${state.admin?'Admin flight mode · all cabins & passes unlocked.':'Your destination is set before departure, and will stay printed on your ticket.'}</p>${state.stage===0?`<div class="actions"><button class="secondary full" onclick="openHouse()">⌂ ${state.house?'Upgrade':'Decorate'} your house · game coins</button></div>`:''}<div class="actions"><button class="text-button" onclick="openShop()">View cabins & fun passes →</button></div></div></aside>`}
function render(){document.getElementById('coin-count').textContent=state.coins;game.innerHTML=`<div class="welcome-row"><div><span class="eyebrow">${state.admin?'ADMIN FLIGHT DECK':'YOUR SKY, YOUR STORY'}</span><h1>Good ${new Date().getHours()<12?'morning':'day'}, ${state.admin?state.adminName:'Aviator'} <span style="color:var(--coral)">✦</span></h1><p>${state.stage===0?'Where shall we take off to today?':`On your way to ${city(state.destination).name} · ${city(state.destination).country}`}</p></div><span class="step-pill">${state.stage===6?'✦ Trip complete':`Journey ${state.stage+1} of 7`}</span></div>${progress()}<div class="content-grid">${panel()}${side()}</div>`;}
function beginTrip(){const origin=document.getElementById('origin-select').value,dest=document.getElementById('dest-select').value;if(origin===dest){toast('Choose two different cities.');return}state.origin=origin;state.destination=dest;save();openShop(true)}
function rideTaxi(){if(!state.admin&&state.coins<35){toast('Not enough game coins. Decorate your house later, or enjoy the starter coins!');return}if(!state.admin)state.coins-=35;setStage(2);toast('Taxi arrived at the airport!')}
function openBag(){modal(`<div class="modal-head"><div><span class="eyebrow">BAG DROP</span><h2>Check your luggage</h2></div><button class="close" onclick="closeModal()">×</button></div><p>Choose your checked bag weight. Your carry-on stays with you.</p><div class="field"><label>SUITCASE WEIGHT · LIMIT 20 KG</label><input id="bag-weight" type="range" min="5" max="28" value="14" oninput="document.getElementById('weight-value').textContent=this.value+' kg'"></div><div class="event-banner">Suitcase: <b id="weight-value">14 kg</b> &nbsp; · &nbsp; Carry-on: 4 kg</div><div class="modal-actions"><button class="primary" onclick="bagConfirm()">Drop my bag →</button></div><p class="inline-note" id="bag-note"></p>`)}
function bagConfirm(){const w=+document.getElementById('bag-weight').value;if(w>20){document.getElementById('bag-note').textContent='That bag is a little heavy — slide it under 20 kg.';return}closeModal();state.bagDone=true;setStage(3);toast(`${w} kg checked. Small bag stays with you!`)}
function securityDone(){const selected=document.querySelectorAll('.bag-item.marked');if(!selected.length){toast('Tap the water bottle to place it in the tray.');return}setStage(4);toast('Security complete — have a lovely flight!')}

