function securityDone(){const selected=document.querySelectorAll('.bag-item.marked');if(!selected.length){toast('Tap the water bottle to place it in the tray.');return}setStage(4);toast('Security complete — have a lovely flight!')}
function modal(html){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal">${html}</div></div>`}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
function openRoute(){beginTrip()}
function openShop(fromTrip=false){chosenClass=state.flightClass;let classes=['Standard','First class','Business class'];modal(`<div class="modal-head"><div><span class="eyebrow">CABIN & FUN PASS</span><h2>Make this trip yours</h2></div><button class="close" onclick="closeModal()">×</button></div><p>Choose your cabin and optional fun pass. Prices show a local-currency estimate converted to Saudi riyals.</p><div class="field"><label>DISPLAY CURRENCY</label><select id="currency-select" onchange="currency=this.value;refreshPrices()">${Object.keys(rates).map(c=>`<option value="${c}" ${c===currency?'selected':''}>${c==='SAR'?'Saudi Riyal':c==='USD'?'US Dollar':c==='EUR'?'Euro':c==='GBP'?'Pound Sterling':c==='AED'?'UAE Dirham':'Indian Rupee'} (${c})</option>`).join('')}</select></div><div class="price-grid">${classes.map(c=>`<button class="price-option ${c===chosenClass?'chosen':''}" onclick="chooseClass('${c}')"><small>${c==='Standard'?'THE CLASSIC':'A LITTLE EXTRA'}</small><b>${c}</b><span class="price" data-sar="${fares[c]}">${fareLabel(fares[c])}</span><small>${fares[c]===0?'Free · game ticket':'One-time fare · demo only'}</small></button>`).join('')}</div><div class="field"><label>OPTIONAL FUN PASS</label><select id="plan-select" onchange="chosenPlan=this.value;refreshPrices()"><option value="No pass">No pass</option>${Object.entries(plans).map(([p,v])=>`<option value="${p}" ${state.pass===p?'selected':''}>${p} pass · ${fareLabel(v)} / ${p.toLowerCase()}</option>`).join('')}</select></div><p class="inline-note" id="shop-note">${state.admin?'Admin benefit: your cabin and pass are free.':''}</p><p class="notice">Demo only: no payment is taken and no real-money purchase is available. Currency figures are illustrative estimates; SAR conversion is shown for reference.</p><div class="modal-actions"><button class="secondary" onclick="closeModal()">Maybe later</button><button class="primary" onclick="confirmCabin(${fromTrip})">${fromTrip?'Set trip & continue':'Save cabin'}</button></div>`)}
function fareLabel(sar){const val=sar/(rates[currency]||1);let amount=currency==='INR'?Math.round(val):Number(val.toFixed(2));return `${amount} ${currency} <small style="font:500 10px 'DM Sans';color:#82918a">≈ ${sar} SAR</small>`}
function refreshPrices(){document.querySelectorAll('[data-sar]').forEach(e=>e.innerHTML=fareLabel(+e.dataset.sar));const sel=document.getElementById('plan-select');if(sel){for(const opt of sel.options){const key=opt.value;if(plans[key])opt.textContent=`${key} pass · ${fareLabel(plans[key]).replace(/<[^>]*>/g,'')} / ${key.toLowerCase()}`}}}
function chooseClass(c){chosenClass=c;document.querySelectorAll('.price-option').forEach(e=>e.classList.toggle('chosen',e.querySelector('b').textContent===c))}
function confirmCabin(fromTrip){const plan=document.getElementById('plan-select')?.value||state.pass;if(!state.admin){state.flightClass=chosenClass;state.pass=plan}else{state.flightClass=chosenClass;state.pass=plan==='No pass'?'Admin pass':plan+' pass'}save();closeModal();if(fromTrip)setStage(1);else render();toast(state.admin?'Admin cabin unlocked — enjoy!':'Cabin saved for your trip!')}
function openBag(){modal(`<div class="modal-head"><div><span class="eyebrow">BAG DROP</span><h2>Check your luggage</h2></div><button class="close" onclick="closeModal()">×</button></div><p>Choose your checked bag weight. Your small carry-on stays with you.</p><div class="field"><label>SUITCASE WEIGHT · LIMIT 20 KG</label><input id="bag-weight" type="range" min="5" max="28" value="14" oninput="document.getElementById('weight-value').textContent=this.value+' kg'"></div><div class="event-banner">Suitcase: <b id="weight-value">14 kg</b> &nbsp; · &nbsp; Carry-on: 4 kg</div><div class="modal-actions"><button class="primary" onclick="bagConfirm()">Drop my bag →</button></div><p class="inline-note" id="bag-note"></p>`)}
function openTicket(){modal(`<div class="modal-head"><div><span class="eyebrow">BOARDING PASS · CB ${String(218+state.stage*7).padStart(3,'0')}</span><h2>Your ticket to ${city(state.destination).name}</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="ticket-large"><div class="ticket-route"><span>${state.origin}</span><span>✈ →</span><span>${state.destination}</span></div><div class="ticket-details"><div><small>From</small><b>${city(state.origin).name}</b></div><div><small>Landing</small><b>${city(state.destination).name}</b></div><div><small>Cabin</small><b>${state.flightClass}</b></div><div><small>Seat</small><b>${state.admin?'1A':'12F'}</b></div><div><small>Boarding</small><b>Gate 07</b></div><div><small>Pass</small><b>${state.pass}</b></div></div></div><p>Your landing destination was printed when you planned your trip. Keep your small luggage with you.</p><div class="modal-actions"><button class="primary" onclick="closeModal();state.flightRound=0;state.stars=0;setStage(5)">Board the plane ✈</button></div>`)}

