function securityDone(){const items=[...document.querySelectorAll('.bag-item')],water=items.find(e=>e.textContent.includes('Water bottle'));if(!water?.classList.contains('marked')){document.getElementById('security-note').textContent='The water bottle needs to go in the tray. Tap it and try again.';return}closeModal();setStage(4);toast('Security complete — have a lovely flight!')}
function openHouse(){modal(`<div class="modal-head"><div><span class="eyebrow">HOME SWEET HOME</span><h2>Make your house lovely</h2></div><button class="close" onclick="closeModal()">×</button></div><p>Decorate your house using game coins earned on your journeys. This never uses real money.</p><div class="price-grid">${[['Cozy porch',100,'🌿'],['Sunny garden',175,'🌻'],['Dreamy rooftop',250,'🌙']].map((x,i)=>`<button class="price-option" onclick="buyHouse(${x[1]},'${x[0]}')"><b>${x[2]} ${x[0]}</b><span class="price">${x[1]} coins</span><small>${state.house>i?'Already added':'Decor upgrade'}</small></button>`).join('')}</div><p class="inline-note" id="house-note"></p><button class="secondary full" onclick="closeModal()">Back to my trip</button>`)}
function buyHouse(cost,name){if(state.coins<cost){document.getElementById('house-note').textContent='You need a few more game coins. Complete a flight to earn more!';return}state.coins-=cost;state.house++;save();render();openHouse();toast(`${name} added to your home!`)}
function openAdmin(){modal(`<div class="modal-head"><div><span class="eyebrow">FLIGHT DECK ACCESS</span><h2>${state.admin?'Admin flight deck':'Hello, captain'}</h2></div><button class="close" onclick="closeModal()">×</button></div>${state.admin?`<div class="admin-panel">Admin mode is active. All cabin fares and fun passes are free, and you can choose any origin and landing city from the world destination list.</div><div class="field"><label>ADMIN DISPLAY NAME</label><input id="admin-name" value="${state.adminName}"></div><div class="modal-actions"><button class="secondary" onclick="state.admin=false;save();closeModal();render()">Leave admin mode</button><button class="primary" onclick="state.adminName=document.getElementById('admin-name').value||'Captain';save();closeModal();render()">Save</button></div>`:`<p>Enter your administrator code to unlock free cabins and passes for this demo.</p><div class="field"><label>ADMIN CODE</label><input id="admin-code" type="password" placeholder="Enter code" autocomplete="off"></div><p class="notice">Demo administrator code: <b>SKY777</b></p><p class="inline-note" id="admin-note"></p><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="checkAdmin()">Unlock flight deck</button></div>`}`)}
function checkAdmin(){const input=document.getElementById('admin-code').value;if(input!=='SKY777'){document.getElementById('admin-note').textContent='That code didn’t work. Try the demo code shown above.';return}state.admin=true;state.flightClass='First class';state.pass='Admin pass';save();closeModal();render();toast('Welcome, admin — all extras are free!')}
function openProfile(){modal(`<div class="modal-head"><div><span class="eyebrow">YOUR PILOT CARD</span><h2>Aviator profile</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="admin-panel">${state.coins} game coins · ${state.stars} sky stars · ${state.house} home upgrades</div><p>Progress saves on this device. All game coins are pretend and have no cash value.</p><button class="secondary full" onclick="closeModal()">Back to my trip</button>`)}
function newTrip(){state.coins+=80+state.stars*15;state.origin=state.destination;state.destination=Object.keys(cities).find(c=>c!==state.origin)||'LHR';state.flightRound=0;state.stars=0;state.flightClass=state.admin?'First class':'Standard';state.stage=0;save();render();toast('Arrival bonus added to your game wallet!')}
let skyChallenge={cloud:0,star:2};const lanes=['left','center','right'];function nextSky(){const cloud=Math.floor(Math.random()*3);let star=Math.floor(Math.random()*3);while(star===cloud)star=Math.floor(Math.random()*3);skyChallenge={cloud,star};}
function fly(lane){const laneIndex=lanes.indexOf(lane);let message;if(laneIndex===skyChallenge.cloud){message='A fluffy cloud! You dodged the bump — no star this time.'}else if(laneIndex===skyChallenge.star){state.stars++;state.coins+=8;message='Beautiful flying! You collected a sky star and 8 game coins.'}else{message='Smooth skies — keep your course.'}state.flightRound++;if(state.flightRound>=5){state.coins+=80+state.stars*15;state.stage=6;save();render();toast(`Landed in ${city(state.destination).name}! Arrival bonus added.`);return}nextSky();save();render();document.getElementById('flight-event').textContent=`${message} Next: cloud in ${lanes[skyChallenge.cloud]}, star in ${lanes[skyChallenge.star]}.`}
const renderBase=render;render=function(){renderBase();if(state.stage===5){document.getElementById('flight-event').textContent=`Cloud in ${lanes[skyChallenge.cloud]} · Sky star in ${lanes[skyChallenge.star]} — choose your lane!`}};
document.getElementById('admin-open').addEventListener('click',openAdmin);document.getElementById('profile-open').addEventListener('click',openProfile);
render();

